/* Preview-only real-browser fixture generated by the verified Orchestrator.
 * No personal data, no public customer routing, no extra services.
 */
import {mkdtemp,mkdir,readFile,copyFile,writeFile,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {executeIdea} from '../engine.mjs';

const onlyBranch='test/orchestrator-real-browser-20261106';
if(process.env.CF_PAGES_BRANCH!==onlyBranch){
  console.log('Synthetic browser QA fixture: skipped outside isolated preview.');
}else{
  const tmp=await mkdtemp(join(tmpdir(),'mz-browser-fixture-'));
  try{
    const idea='أريد تطبيق ويب بسيط لقائمة مهام يومية يحتفظ بما أضيفه على جهازي';
    const result=await executeIdea({idea,title:'قائمة اختبار اصطناعية'},{outputRoot:tmp});
    if(!result.ok||result.state!=='staging_verified'||result.receipt?.source_verified!==true)
      throw new Error('synthetic_app_unverified');
    const target=fileURLToPath(new URL('../../site/qa-orchestrator/',import.meta.url));
    await mkdir(target,{recursive:true});
    for(const name of ['app.js','styles.css']){
      await copyFile(join(result.artifact_path,'..',name),join(target,name));
    }
    // This synthetic test script is never included in the ZIP delivered by Orchestrator.
    await copyFile(fileURLToPath(new URL('./browser-acceptance.js',import.meta.url)),join(target,'browser-acceptance.js'));
    const source=await readFile(join(result.artifact_path,'..','index.html'),'utf8');
    if(!source.includes('</body>'))throw new Error('invalid_app_html');
    const html=source.replace('</body>','<script defer src="./browser-acceptance.js"></script></body>');
    await writeFile(join(target,'index.html'),html);
    console.log('Synthetic browser fixture built by reviewed Orchestrator, awaiting Chromium acceptance.');
  }finally{
    await rm(tmp,{recursive:true,force:true});
  }
}
